//! Dedicated bounded facet DTOs; native API layouts never cross the transport.
use serde::{Deserialize, Serialize};
/// Transport representation of `Generated`.
#[derive(Clone, Debug, Eq, PartialEq, Serialize, Deserialize)]
pub enum WireGenerated {
    /// An ordinary column (it may still have a default).
    No,
    /// `GENERATED ALWAYS AS IDENTITY`.
    IdentityAlways,
    /// `GENERATED BY DEFAULT AS IDENTITY`.
    IdentityByDefault,
    /// `GENERATED ALWAYS AS (expression) STORED`; the expression is the default.
    Stored,
    /// `MySQL` `AUTO_INCREMENT`.
    AutoIncrement,
}
impl From<openrows_driver_api::schema::Generated> for WireGenerated {
    fn from(value: openrows_driver_api::schema::Generated) -> Self {
        match value {
            openrows_driver_api::schema::Generated::No => Self::No,
            openrows_driver_api::schema::Generated::IdentityAlways => Self::IdentityAlways,
            openrows_driver_api::schema::Generated::IdentityByDefault => Self::IdentityByDefault,
            openrows_driver_api::schema::Generated::Stored => Self::Stored,
            openrows_driver_api::schema::Generated::AutoIncrement => Self::AutoIncrement,
        }
    }
}
impl From<WireGenerated> for openrows_driver_api::schema::Generated {
    fn from(value: WireGenerated) -> Self {
        match value {
            WireGenerated::No => Self::No,
            WireGenerated::IdentityAlways => Self::IdentityAlways,
            WireGenerated::IdentityByDefault => Self::IdentityByDefault,
            WireGenerated::Stored => Self::Stored,
            WireGenerated::AutoIncrement => Self::AutoIncrement,
        }
    }
}
